actions.script:
# FIX APPLE BY THIEN PHAN GSM — chuẩn bị máy tính trước khi làm iPhone / iPad (thuật toán bao hàm của GSM Pro Toolkit)
# @algo fix-apple-toan-dien | Fix Apple toàn diện (iTunes + UsbDk) | admin
# @input bonjour | tool | Bonjour 64-bit (Bonjour64.msi) | bonjour64
# @input itunes | tool | iTunes 64-bit (iTunes64.exe) | itunes64
# @input usbdk | tool | UsbDk 64-bit (UsbDk64.msi) | usbdk64
#
# Trong tool: bật "Chạy với quyền quản trị". Nút có chữ "chỉ kiểm tra" trong tên → CHỈ KIỂM TRA, không sửa gì.
# Chạy tay:   .\Fix-Apple-Toan-Dien.ps1 [-ChiKiemTra] [-Bonjour <tệp|thư mục>] [-iTunes <tệp|thư mục>] [-UsbDk <tệp|thư mục>]
#             (không chỉ định thì tìm 3 tệp cạnh script)
# Mã thoát:   0 = hoàn tất · 2 = phải KHỞI ĐỘNG LẠI rồi chạy lại (chưa xong) · 1 = có mục thất bại
param([switch]$ChiKiemTra, [string]$Bonjour, [string]$iTunes, [string]$UsbDk, [switch]$KhongCho)

$ErrorActionPreference = 'Continue'
$ProgressPreference = 'SilentlyContinue'
if ($env:GSM_BUTTON -and $env:GSM_BUTTON -match 'chỉ kiểm tra') { $ChiKiemTra = [switch]$true }
if (-not $Bonjour) { $Bonjour = $env:GSM_IN_BONJOUR }
if (-not $iTunes) { $iTunes = $env:GSM_IN_ITUNES }
if (-not $UsbDk) { $UsbDk = $env:GSM_IN_USBDK }

# ───────────────────────── quyền quản trị ─────────────────────────
$laAdmin = ([Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)
if (-not $laAdmin -and -not $ChiKiemTra) {
    $a = @('-NoProfile', '-ExecutionPolicy', 'Bypass', '-File', "`"$PSCommandPath`"")
    if ($Bonjour) { $a += @('-Bonjour', "`"$Bonjour`"") }
    if ($iTunes) { $a += @('-iTunes', "`"$iTunes`"") }
    if ($UsbDk) { $a += @('-UsbDk', "`"$UsbDk`"") }
    if ($KhongCho) { $a += '-KhongCho' }
    try { $p = Start-Process powershell.exe -ArgumentList $a -Verb RunAs -Wait -PassThru -ErrorAction Stop; exit $p.ExitCode }
    catch { Write-Host 'Chưa được cấp quyền quản trị (bấm "Không" ở hộp UAC?) — chưa làm gì.' -ForegroundColor Red; exit 1 }
}

# ───────────────────────── nơi ghi báo cáo ─────────────────────────
$Goc = Join-Path $env:ProgramData 'GSM Pro Toolkit\FixApple'
if ($ChiKiemTra) { $Goc = Join-Path $env:TEMP 'gsm-fix-apple-kiemtra' }
$ThuMuc = Join-Path $Goc (Get-Date -Format 'yyyyMMdd-HHmmss')
New-Item -ItemType Directory -Force $ThuMuc | Out-Null
if (-not $ChiKiemTra) {
    # bản sao Lockdown chứa khóa ghép đôi: chỉ Quản trị viên + SYSTEM được đọc
    & icacls.exe $Goc '/inheritance:r' '/grant:r' '*S-1-5-32-544:(OI)(CI)F' '*S-1-5-18:(OI)(CI)F' '/Q' | Out-Null
}
try { Start-Transcript -Path (Join-Path $ThuMuc 'bao-cao.txt') -ErrorAction Stop | Out-Null } catch {}
$TepGoc = Join-Path $Goc 'gia-tri-goc.json'

$script:KetQua = New-Object System.Collections.ArrayList
$script:CanReboot = $false
$script:GoiYReboot = @()
$script:LyDoKet = ''

function Write-Muc($t) { Write-Host ''; Write-Host $t -ForegroundColor Cyan }
function Write-Dong($t) { Write-Host "    - $t" }
function Add-KetQua($muc, $loai, $chiTiet) {
    [void]$script:KetQua.Add([pscustomobject]@{ Muc = $muc; Loai = $loai; ChiTiet = $chiTiet })
    $mau = @{ OK = 'Green'; 'BỎ QUA' = 'Gray'; 'CẢNH BÁO' = 'Yellow'; 'CẦN REBOOT' = 'Yellow'; 'LỖI' = 'Red' }[$loai]
    Write-Host "    => $loai : $chiTiet" -ForegroundColor $mau
    if ($loai -eq 'CẦN REBOOT') { $script:CanReboot = $true }
}
function Assert-DuocSua { if ($ChiKiemTra) { throw 'LỖI NỘI BỘ: chế độ chỉ kiểm tra không được phép sửa máy.' } }

# ───────────────────────── hàm dùng chung ─────────────────────────
function Find-NguyenLieu($duongDan, $mau) {
    $noi = $duongDan
    if (-not $noi) { $noi = $PSScriptRoot }
    if (Test-Path -LiteralPath $noi -PathType Leaf) { return (Get-Item -LiteralPath $noi).FullName }
    if (Test-Path -LiteralPath $noi -PathType Container) {
        $f = Get-ChildItem -LiteralPath $noi -Recurse -File -Filter $mau -ErrorAction SilentlyContinue | Select-Object -First 1
        if ($f) { return $f.FullName }
    }
    return $null
}
function Test-ChuKy($tep, $tenKy) {
    $s = Get-AuthenticodeSignature -LiteralPath $tep
    return ($s.Status -eq 'Valid' -and $s.SignerCertificate.Subject -match $tenKy)
}
function Get-DaCai($mau) {
    $k = 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\*', 'HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall\*'
    Get-ItemProperty $k -ErrorAction SilentlyContinue | Where-Object { $_.DisplayName -match $mau } | Select-Object -First 1
}
function Get-MsiThuocTinh([string]$tep, [string]$ten) {
    try {
        $wi = New-Object -ComObject WindowsInstaller.Installer
        $db = $wi.GetType().InvokeMember('OpenDatabase', 'InvokeMethod', $null, $wi, @([string]$tep, 0))
        $v = $db.GetType().InvokeMember('OpenView', 'InvokeMethod', $null, $db, @("SELECT Value FROM Property WHERE Property='$ten'"))
        $null = $v.GetType().InvokeMember('Execute', 'InvokeMethod', $null, $v, $null)
        $r = $v.GetType().InvokeMember('Fetch', 'InvokeMethod', $null, $v, $null)
        $kq = $null
        if ($r) { $kq = $r.GetType().InvokeMember('StringData', 'GetProperty', $null, $r, 1) }
        $null = $v.GetType().InvokeMember('Close', 'InvokeMethod', $null, $v, $null)
        foreach ($o in $r, $v, $db, $wi) { if ($o) { [void][Runtime.InteropServices.Marshal]::ReleaseComObject($o) } }
        return $kq
    } catch { return $null }
}
function Compare-PhienBan($a, $b) { try { return ([version]$a).CompareTo([version]$b) } catch { return 0 } }
function Test-MsiXong($ma) { return ($ma -eq 0 -or $ma -eq 3010 -or $ma -eq 1641) }

# Chạy msiexec ẩn, đợi xong, có nhật ký chi tiết. 1618 (đang có bộ cài khác) → đợi rồi thử lại.
function Invoke-Msi([string[]]$thamSo, [string]$ten) {
    Assert-DuocSua
    $ma = 1618
    for ($lan = 1; $lan -le 12; $lan++) {
        $log = Join-Path $ThuMuc ("msi-{0}-{1}.log" -f $ten, (Get-Date -Format 'HHmmssfff'))
        $p = Start-Process msiexec.exe -ArgumentList ($thamSo + @('/qn', '/norestart', '/l*v', "`"$log`"")) -Wait -PassThru
        $ma = $p.ExitCode
        if ($ma -ne 1618) { break }
        Write-Dong 'Đang có bộ cài khác chạy (1618) — đợi 20 giây rồi thử lại…'
        Start-Sleep -Seconds 20
    }
    Write-Dong "msiexec ($ten) trả mã $ma"
    if (-not (Test-MsiXong $ma) -and (Test-Path -LiteralPath $log)) {
        # in đoạn ngay trước "Return value 3" = chỗ bộ cài thật sự hỏng
        $dong = @(Get-Content -LiteralPath $log -ErrorAction SilentlyContinue)
        $i = ($dong | Select-String -SimpleMatch 'Return value 3' | Select-Object -First 1).LineNumber
        if ($i) { $dong[([Math]::Max(0, $i - 7))..($i - 1)] | ForEach-Object { Write-Host "      | $_" -ForegroundColor DarkYellow } }
        Write-Dong "Nhật ký đầy đủ: $log"
    }
    if ($ma -eq 3010 -or $ma -eq 1641) { $script:GoiYReboot += $ten }
    return $ma
}
function Start-DichVu($ten) {
    Assert-DuocSua
    $s = Get-Service -Name $ten -ErrorAction SilentlyContinue
    if (-not $s) { return $false }
    Set-Service -Name $ten -StartupType Automatic -ErrorAction SilentlyContinue
    if ($s.Status -ne 'Running') { Start-Service -Name $ten -ErrorAction SilentlyContinue }
    for ($i = 0; $i -lt 20; $i++) { if ((Get-Service -Name $ten).Status -eq 'Running') { return $true }; Start-Sleep -Milliseconds 500 }
    return $false
}
function Get-NguonDien($nhom, $muc) {
    $o = (& powercfg.exe /q SCHEME_CURRENT $nhom $muc 2>$null) -join "`n"
    $m = @([regex]::Matches($o, '0x[0-9a-fA-F]{8}'))
    if ($m.Count -lt 2) { return $null }
    return @([Convert]::ToInt32($m[$m.Count - 2].Value, 16), [Convert]::ToInt32($m[$m.Count - 1].Value, 16))
}
$UsbNhom = '2a737441-1930-4402-8d77-b2bebba308a3'
$UsbMuc = '48e6b7a6-50f5-4782-a5d4-53bb8f07e226'
$KhoaUac = 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\System'
$ThuMucLockdown = Join-Path $env:ProgramData 'Apple\Lockdown'

function Test-TempChoEveryone {
    try {
        $r = (Get-Acl 'C:\Windows\Temp' -ErrorAction Stop).GetAccessRules($true, $true, [Security.Principal.SecurityIdentifier])
        return [bool]($r | Where-Object { $_.IdentityReference.Value -eq 'S-1-1-0' -and ($_.FileSystemRights -band [Security.AccessControl.FileSystemRights]::FullControl) -eq [Security.AccessControl.FileSystemRights]::FullControl })
    } catch { return $null }
}
# Lưu giá trị GỐC đúng 1 lần (lần chạy sau không được ghi đè bằng giá trị đã sửa) + sinh script khôi phục
function Save-GiaTriGoc {
    Assert-DuocSua
    if (-not (Test-Path -LiteralPath $TepGoc)) {
        $g = [pscustomobject]@{
            Uac = (Get-ItemProperty $KhoaUac -ErrorAction SilentlyContinue).ConsentPromptBehaviorAdmin
            TempDaChoEveryone = Test-TempChoEveryone
            ManHinh = Get-NguonDien 'SUB_VIDEO' 'VIDEOIDLE'
            Ngu = Get-NguonDien 'SUB_SLEEP' 'STANDBYIDLE'
            Usb = Get-NguonDien $UsbNhom $UsbMuc
        }
        $g | ConvertTo-Json | Set-Content -LiteralPath $TepGoc -Encoding UTF8
    }
    $g = Get-Content -LiteralPath $TepGoc -Raw -Encoding UTF8 | ConvertFrom-Json
    $d = @('# Khôi phục UAC / quyền thư mục Temp / nguồn điện về giá trị trước lần Fix Apple đầu tiên. Chạy bằng PowerShell quyền quản trị.')
    if ($null -ne $g.Uac) { $d += "Set-ItemProperty '$KhoaUac' -Name ConsentPromptBehaviorAdmin -Type DWord -Value $($g.Uac)" }
    if ($g.TempDaChoEveryone -eq $false) { $d += "icacls.exe 'C:\Windows\Temp' /remove:g '*S-1-1-0' /T /C /Q" }
    foreach ($x in @(@('SUB_VIDEO', 'VIDEOIDLE', $g.ManHinh), @('SUB_SLEEP', 'STANDBYIDLE', $g.Ngu), @($UsbNhom, $UsbMuc, $g.Usb))) {
        if ($x[2]) { $d += "powercfg /SETACVALUEINDEX SCHEME_CURRENT $($x[0]) $($x[1]) $($x[2][0])"; $d += "powercfg /SETDCVALUEINDEX SCHEME_CURRENT $($x[0]) $($x[1]) $($x[2][1])" }
    }
    $d += 'powercfg /SETACTIVE SCHEME_CURRENT'
    $d | Set-Content -LiteralPath (Join-Path $Goc 'khoi-phuc.ps1') -Encoding UTF8
}

# ───────────────────────── iTunes / Apple Mobile Device Support ─────────────────────────
# iTunes64.exe là vỏ tự giải nén chứa 1 gói CAB: tách ra bằng expand.exe có sẵn của Windows (không chạy bộ cài).
function Expand-BoITunes($exe, $dich) {
    New-Item -ItemType Directory -Force $dich | Out-Null
    $b = [IO.File]::ReadAllBytes($exe)
    $s = [Text.Encoding]::GetEncoding(28591).GetString($b)
    $i = 0; $viTri = -1; $dai = 0
    while (($i = $s.IndexOf("MSCF`0`0`0`0", $i, [StringComparison]::Ordinal)) -ge 0) {
        $n = [BitConverter]::ToUInt32($b, $i + 8)
        if ($n -gt 1MB -and ($i + $n) -le $b.Length -and $n -gt $dai) { $viTri = $i; $dai = $n }
        $i += 4
    }
    if ($viTri -lt 0) { return $false }
    $cab = Join-Path $dich 'itunes.cab'
    $fs = [IO.File]::Create($cab); $fs.Write($b, $viTri, [int]$dai); $fs.Close()
    & expand.exe $cab '-F:*.msi' $dich | Out-Null
    Remove-Item -LiteralPath $cab -Force -ErrorAction SilentlyContinue
    return $true
}
function Get-TrangThaiAmds {
    $cai = Get-DaCai '^Apple Mobile Device Support'
    $reg = Get-ItemProperty 'HKLM:\SOFTWARE\Apple Inc.\Apple Mobile Device Support' -ErrorAction SilentlyContinue
    $dll = (Get-ItemProperty 'HKLM:\SOFTWARE\Apple Inc.\Apple Mobile Device Support\Shared' -ErrorAction SilentlyContinue).MobileDeviceDLL
    $dv = Get-Service -Name 'Apple Mobile Device Service' -ErrorAction SilentlyContinue
    $thieu = @()
    if (-not $cai) { $thieu += 'chưa có trong danh sách đã cài' }
    if (-not $reg.Version) { $thieu += 'thiếu khóa registry phiên bản' }
    if (-not ($dll -and (Test-Path -LiteralPath $dll))) { $thieu += 'thiếu MobileDevice.dll' }
    if (-not $dv) { $thieu += 'thiếu dịch vụ Apple Mobile Device Service' }
    $ver = $reg.Version; if ($cai.DisplayVersion) { $ver = $cai.DisplayVersion }
    $inf = $null; if ($reg.InstallDir) { $inf = Join-Path $reg.InstallDir 'Drivers\usbaapl64.inf' }
    [pscustomobject]@{ DaCai = [bool]$cai; Ma = $cai.PSChildName; PhienBan = $ver; Thieu = $thieu; Khoe = ($thieu.Count -eq 0); DichVu = "$($dv.Status)"; Inf = $inf }
}
function Test-DriverAppleTrongKho { return [bool]((& pnputil.exe /enum-drivers 2>$null) -match 'usbaapl64\.inf') }
function Get-TrangThaiITunes {
    $cai = Get-DaCai '^iTunes$'
    $reg = Get-ItemProperty 'HKLM:\SOFTWARE\Apple Computer, Inc.\iTunes' -ErrorAction SilentlyContinue
    $exe = Join-Path $env:ProgramFiles 'iTunes\iTunes.exe'
    $thieu = @()
    if (-not $cai) { $thieu += 'chưa có trong danh sách đã cài' }
    if (-not $reg.Version) { $thieu += 'thiếu khóa registry phiên bản' }
    if (-not (Test-Path -LiteralPath $exe)) { $thieu += 'thiếu iTunes.exe' }
    $ver = $cai.DisplayVersion; if (-not $ver) { $ver = $reg.Version }
    [pscustomobject]@{ DaCai = [bool]$cai; Ma = $cai.PSChildName; PhienBan = $ver; Thieu = $thieu; Khoe = ($thieu.Count -eq 0) }
}
# iTunes bản Microsoft Store chiếm quyền kết nối iPhone → phải gỡ, thay bằng bản EXE ở mục nguyên liệu. Tên gói khớp CHÍNH XÁC để không gỡ nhầm app khác.
$TenITunesStore = 'AppleInc.iTunes'
function Get-ITunesStore {
    $kq = [pscustomobject]@{ Goi = @(); CaiSan = @(); DocDuoc = $true; MoiTaiKhoan = $true; Loi = '' }
    try { $kq.Goi = @(Get-AppxPackage -Name $TenITunesStore -AllUsers -ErrorAction Stop) }
    catch {
        # không đủ quyền xem mọi tài khoản → xem tài khoản đang dùng
        $kq.MoiTaiKhoan = $false
        try { $kq.Goi = @(Get-AppxPackage -Name $TenITunesStore -ErrorAction Stop) } catch { $kq.DocDuoc = $false; $kq.Loi = $_.Exception.Message }
    }
    # gói cài sẵn của máy: còn nó thì tài khoản Windows mới lại có bản Store (cần quyền quản trị mới đọc được)
    try { $kq.CaiSan = @(Get-AppxProvisionedPackage -Online -ErrorAction Stop | Where-Object { $_.DisplayName -eq $TenITunesStore }) } catch {}
    return $kq
}
function Format-ITunesStore($s) {
    $v = @($s.Goi | ForEach-Object { "$($_.Version)" }) + @($s.CaiSan | ForEach-Object { "$($_.Version)" }) | Where-Object { $_ } | Select-Object -Unique
    return ($v -join ', ')
}
# Gỡ và NGHIỆM THU bằng cách dò lại. Không có bản Store thì không làm gì.
function Remove-ITunesStore {
    Assert-DuocSua
    $s = Get-ITunesStore
    if (-not $s.DocDuoc) { Add-KetQua 'iTunes bản Microsoft Store' 'CẢNH BÁO' "không kiểm tra được máy có bản Store hay không ($($s.Loi))"; return }
    if (-not $s.Goi.Count -and -not $s.CaiSan.Count) { Write-Dong 'iTunes bản Microsoft Store: không có.'; return }
    $ban = Format-ITunesStore $s
    Write-Dong "Phát hiện iTunes bản Microsoft Store ($ban) — gỡ, rồi dùng bản EXE ở mục nguyên liệu thay thế…"
    foreach ($g in $s.Goi) {
        try { Remove-AppxPackage -Package $g.PackageFullName -AllUsers -ErrorAction Stop }
        catch {
            Write-Dong "Gỡ cho mọi tài khoản chưa được ($($_.Exception.Message)) — gỡ ở tài khoản đang dùng…"
            try { Remove-AppxPackage -Package $g.PackageFullName -ErrorAction Stop } catch { Write-Dong "Gỡ chưa được: $($_.Exception.Message)" }
        }
    }
    foreach ($c in $s.CaiSan) {
        try { $null = Remove-AppxProvisionedPackage -Online -PackageName $c.PackageName -ErrorAction Stop } catch { Write-Dong "Chưa bỏ được gói cài sẵn của máy: $($_.Exception.Message)" }
    }
    $con = Get-ITunesStore
    if (-not $con.DocDuoc) { Add-KetQua 'iTunes bản Microsoft Store' 'CẢNH BÁO' "đã chạy lệnh gỡ nhưng không dò lại được ($($con.Loi))" }
    elseif ($con.Goi.Count) { Add-KetQua 'iTunes bản Microsoft Store' 'LỖI' "vẫn còn bản $(Format-ITunesStore $con) — gỡ tay ở Settings → Apps → iTunes rồi chạy lại" }
    elseif ($con.CaiSan.Count) { Add-KetQua 'iTunes bản Microsoft Store' 'CẢNH BÁO' "đã gỡ bản $ban, nhưng gói cài sẵn của máy còn — tài khoản Windows mới có thể lại có bản Store" }
    else { Add-KetQua 'iTunes bản Microsoft Store' 'OK' "đã gỡ bản $ban" }
}
# Việc cần làm với 1 gói: GIU (đủ & không cũ hơn) · CAI (chưa có) · NANGCAP (cũ hơn) · LAMLAI (có mà thiếu thành phần)
function Get-ViecCan($tt, $phienBanGoi) {
    if ($tt.Khoe) { if ((Compare-PhienBan $tt.PhienBan $phienBanGoi) -ge 0) { return 'GIU' } else { return 'NANGCAP' } }
    if (-not $tt.DaCai) { return 'CAI' }
    return 'LAMLAI'
}
# Cài 1 gói rồi NGHIỆM THU bằng trạng thái thật; chưa đạt thì gỡ sạch bản đang có và cài lại 1 lần.
function Install-Goi($ten, $msi, [scriptblock]$layTrangThai, $viec) {
    Assert-DuocSua
    $q = "`"$msi`""
    $maGoi = Get-MsiThuocTinh $msi 'ProductCode'
    $tt = & $layTrangThai
    if ($viec -eq 'LAMLAI') {
        if ($tt.Ma -eq $maGoi) { $null = Invoke-Msi @('/i', $q, 'REINSTALL=ALL', 'REINSTALLMODE=vamus') "$ten-sua" }
        else { $null = Invoke-Msi @('/x', $tt.Ma) "$ten-go"; $null = Invoke-Msi @('/i', $q) "$ten-cai" }
    } else { $null = Invoke-Msi @('/i', $q) "$ten-cai" }
    $tt = & $layTrangThai
    if (-not $tt.Khoe) {
        Write-Dong "Nghiệm thu lần 1 CHƯA đạt ($($tt.Thieu -join '; ')) — gỡ sạch rồi cài lại."
        if ($tt.Ma) { $null = Invoke-Msi @('/x', $tt.Ma) "$ten-go-lai" }
        $null = Invoke-Msi @('/i', $q) "$ten-cai-lai"
        $tt = & $layTrangThai
    }
    return $tt
}

# ───────────────────────── UsbDk ─────────────────────────
# Vì sao bộ cài UsbDk hay bắt khởi động lại (đọc mã nguồn daynix/UsbDk): lúc gỡ nó nạp lại bộ điều khiển USB nhưng BỎ QUA kết quả, không bao giờ
# gửi lệnh dừng driver, rồi xóa tệp + dịch vụ → driver còn trong bộ nhớ thì dịch vụ bị "chờ xóa" và lần cài sau không tạo lại được.
# Quy tắc ở đây: (1) chưa cần thì không gỡ; (2) CHỈ xóa khi đã thấy driver DỪNG HẲN; (3) không dừng được thì trả lại nguyên trạng, không để dở dang;
# (4) tin vào trạng thái thật + chạy thử, không tin cờ "cần khởi động lại" của bộ cài.
$UsbDkThuMuc = Join-Path $env:ProgramFiles 'UsbDk Runtime Library'
$UsbDkSys = Join-Path $env:windir 'System32\drivers\UsbDk.sys'
$UsbDkKhoa = 'HKLM:\SYSTEM\CurrentControlSet\Services\UsbDk'
$UsbDkCtl = Join-Path $UsbDkThuMuc 'UsbDkController.exe'
$LopUsb = '{36FC9E60-C465-11CF-8056-444553540000}'
$TepUsbDk = Join-Path $Goc 'usbdk-trang-thai.json'
$TepCuuUsb = Join-Path $env:ProgramData 'GSM-cuu-usb.cmd'

function Get-BoLocUsbDk {
    foreach ($k in Get-ChildItem 'HKLM:\SYSTEM\CurrentControlSet\Control\Class' -ErrorAction SilentlyContinue) {
        $p = Get-ItemProperty -LiteralPath $k.PSPath -ErrorAction SilentlyContinue
        foreach ($t in 'UpperFilters', 'LowerFilters') {
            if (@($p.$t) -contains 'UsbDk') { [pscustomobject]@{ Khoa = $k.PSPath; Lop = $k.PSChildName; Ten = $t; GiaTri = [string[]]@($p.$t) } }
        }
    }
}
# trạng thái driver trong Windows: KHONG_CO / STOPPED / RUNNING / STOP_PENDING / KHAC
function Get-DriverUsbDk {
    $o = (& sc.exe query UsbDk 2>$null) -join "`n"
    if ($o -notmatch 'STATE\s*:\s*(\d)') { return 'KHONG_CO' }
    switch ($Matches[1]) { '1' { 'STOPPED' } '3' { 'STOP_PENDING' } '4' { 'RUNNING' } default { 'KHAC' } }
}
# Thử thật driver: "UsbDkController -n" liệt kê thiết bị USB qua driver (0 = được). Quá 30 giây = kẹt.
function Test-UsbDkChay($ctl) {
    $ra = Join-Path $ThuMuc 'usbdk-liet-ke.txt'
    try {
        $p = Start-Process -FilePath $ctl -ArgumentList '-n' -PassThru -NoNewWindow -RedirectStandardOutput $ra -ErrorAction Stop
        $null = $p.Handle
        if (-not $p.WaitForExit(30000)) { try { $p.Kill() } catch {}; return 'KẸT (không trả lời sau 30 giây)' }
        if ($p.ExitCode -eq 0) { return 'ĐẠT' }
        return "KHÔNG ĐẠT (mã $($p.ExitCode))"
    } catch { return "KHÔNG ĐẠT ($($_.Exception.Message))" }
}
function Get-TrangThaiUsbDk {
    $cai = Get-DaCai '^UsbDk'
    $khoa = Test-Path $UsbDkKhoa
    $choXoa = $khoa -and ((Get-ItemProperty $UsbDkKhoa -ErrorAction SilentlyContinue).DeleteFlag -eq 1)
    $sys = Test-Path -LiteralPath $UsbDkSys
    $coCtl = Test-Path -LiteralPath $UsbDkCtl
    $loc = @(Get-BoLocUsbDk)
    $drv = Get-DriverUsbDk
    $thu = 'chưa thử'
    if ($sys -and $khoa -and $coCtl -and -not $choXoa) { $thu = Test-UsbDkChay $UsbDkCtl }
    $loai = 'HONG'
    if ($choXoa) { $loai = 'CHO_XOA' }
    elseif ($thu -eq 'ĐẠT' -and $loc.Count -gt 0) { $loai = 'TOT' }
    elseif (-not $cai -and -not $khoa -and -not $sys -and -not $coCtl -and $loc.Count -eq 0) { $loai = 'CHUA_CAI' }
    [pscustomobject]@{ Loai = $loai; MsiMa = $cai.PSChildName; DichVu = $khoa; TepSys = $sys; Ctl = $coCtl; BoLoc = $loc; Driver = $drv; Thu = $thu }
}
function Write-TrangThaiUsbDk($u) {
    $co = { param($x) if ($x) { 'có' } else { 'KHÔNG' } }
    Write-Dong "Mục đã cài: $(& $co $u.MsiMa) · dịch vụ: $(& $co $u.DichVu) · UsbDk.sys: $(& $co $u.TepSys) · thư viện: $(& $co $u.Ctl) · bộ lọc USB: $(@($u.BoLoc).Count) · driver: $($u.Driver) · chạy thử: $($u.Thu)"
}
function Get-BoDieuKhienUsb {
    $tatCa = @(Get-PnpDevice -PresentOnly -Class USB -ErrorAction SilentlyContinue)
    [pscustomobject]@{
        That = @($tatCa | Where-Object { $_.InstanceId -like 'PCI\*' })
        Ao = @($tatCa | Where-Object { $_.InstanceId -notlike 'PCI\*' -and $_.FriendlyName -match 'Host Controller' })
        UsbQuaMang = @($tatCa | Where-Object { $_.InstanceId -like 'KERNELPRO\*' }).Count
    }
}
# chương trình đang giữ UsbDk (đã nạp thư viện UsbDkHelper.dll). Giới hạn: chương trình 32-bit có thể không lộ danh sách thư viện.
function Get-TienTrinhGiuUsbDk {
    Get-Process -ErrorAction SilentlyContinue | Where-Object { $_.Id -ne $PID } | Where-Object { try { [bool]($_.Modules | Where-Object { $_.ModuleName -eq 'UsbDkHelper.dll' }) } catch { $false } }
}
function Close-TienTrinhGiuUsbDk {
    Assert-DuocSua
    $ds = @(@(Get-TienTrinhGiuUsbDk) + @(Get-Process -Name 'UsbDkController', 'UsbDkInstHelper' -ErrorAction SilentlyContinue))
    foreach ($p in $ds) { Write-Dong "Đóng chương trình đang giữ UsbDk: $($p.ProcessName) (PID $($p.Id))"; Stop-Process -Id $p.Id -Force -ErrorAction SilentlyContinue }
    if ($ds.Count) { Start-Sleep -Seconds 2 }
}
# Nạp lại USB là đứt MỌI thiết bị USB vài giây (bộ cài UsbDk chính thức cũng làm vậy). Trả lý do nếu KHÔNG an toàn.
function Test-AnToanNapLaiUsb {
    $dia = @(Get-Disk -ErrorAction SilentlyContinue | Where-Object { $_.BusType -eq 'USB' })
    if (@($dia | Where-Object { $_.IsBoot -or $_.IsSystem }).Count) { return 'Windows đang chạy từ ổ USB' }
    for ($i = 0; $i -lt 60 -and $dia.Count; $i++) {
        if ($i -eq 0) { Write-Host '    !! HÃY RÚT ổ cứng / USB lưu trữ (tránh hỏng dữ liệu khi nạp lại cổng USB) — đợi tối đa 60 giây…' -ForegroundColor Yellow }
        Start-Sleep -Seconds 1
        $dia = @(Get-Disk -ErrorAction SilentlyContinue | Where-Object { $_.BusType -eq 'USB' })
    }
    if ($dia.Count) { return 'còn ổ lưu trữ USB đang cắm' }
    if (@(Get-NetAdapter -Physical -ErrorAction SilentlyContinue | Where-Object { $_.Status -eq 'Up' -and $_.PnPDeviceID -like 'USB\*' }).Count) { Write-Dong '⚠ Máy đang dùng mạng qua USB — mạng sẽ đứt vài giây.' }
    return $null
}
# Khởi động lại TỪNG bộ điều khiển USB thật (không khởi động lại máy). Trả danh sách bộ điều khiển KHÔNG chịu nạp lại.
function Restart-BoDieuKhienUsb {
    Assert-DuocSua
    $bd = Get-BoDieuKhienUsb
    $tuChoi = @()
    foreach ($d in $bd.That) {
        Write-Dong "Nạp lại: $($d.FriendlyName) (chuột / bàn phím USB chớp vài giây)…"
        $ra = & pnputil.exe /restart-device "$($d.InstanceId)" 2>&1
        $ma = $LASTEXITCODE
        if ($ma -ne 0) { $tuChoi += "$($d.FriendlyName) (mã $ma)"; Write-Dong "  không nạp lại được: $(($ra | Where-Object { "$_".Trim() } | Select-Object -Last 1))" }
    }
    Start-Sleep -Seconds 4
    return , $tuChoi
}
# Bộ cứu: nếu sau khi cài / gỡ UsbDk mà chuột, bàn phím USB chết hoặc máy treo lúc khởi động → chạy tệp này trong WinRE.
function New-BoCuuUsb {
    Assert-DuocSua
    $k = "HKLM:\SYSTEM\CurrentControlSet\Control\Class\$LopUsb"
    $tot = @(@((Get-ItemProperty $k -ErrorAction SilentlyContinue).UpperFilters) | Where-Object { $_ -and $_ -ne 'UsbDk' })
    $dich = "`"HKLM\gsmcuu\ControlSet001\Control\Class\$LopUsb`""
    $dongLoc = "reg delete $dich /v UpperFilters /f"
    if ($tot.Count) { $dongLoc = "reg add $dich /v UpperFilters /t REG_MULTI_SZ /d `"$($tot -join '\0')`" /f" }
    @(
        '@echo off'
        'rem CUU USB (chay trong WinRE: Troubleshoot - Advanced options - Command Prompt)'
        'rem Neu o Windows trong WinRE khong phai C: thi doi chu C: o dong duoi cho dung.'
        'reg load HKLM\gsmcuu C:\Windows\System32\config\SYSTEM'
        'rem 1) bo UsbDk khoi bo loc USB TRUOC  2) roi moi tat dich vu UsbDk'
        $dongLoc
        'reg add "HKLM\gsmcuu\ControlSet001\Services\UsbDk" /v Start /t REG_DWORD /d 4 /f'
        'reg unload HKLM\gsmcuu'
        'echo Xong. Chon "Continue" de vao Windows.'
    ) | Set-Content -LiteralPath $TepCuuUsb -Encoding ASCII
    Write-Dong "Bộ cứu USB (phòng khi chuột/phím USB chết): $TepCuuUsb — nên chụp ảnh đường dẫn này."
    try { Checkpoint-Computer -Description 'GSM truoc khi sua UsbDk' -RestorePointType MODIFY_SETTINGS -ErrorAction Stop -WarningAction SilentlyContinue; Write-Dong 'Đã yêu cầu tạo điểm khôi phục hệ thống.' }
    catch { Write-Dong 'Không tạo được điểm khôi phục (máy đang tắt System Protection) — vẫn còn bộ cứu USB ở trên.' }
}
# GỠ NÓNG bước 1: tách driver khỏi Windows mà không khởi động lại. $true = driver đã dừng hẳn (mới được phép xóa).
function Dismount-UsbDk {
    Assert-DuocSua
    $loc = @(Get-BoLocUsbDk)
    if (-not $loc.Count -and (Get-DriverUsbDk) -in 'STOPPED', 'KHONG_CO') { return $true }
    $loc | Select-Object Lop, Ten, GiaTri | ConvertTo-Json -Depth 4 | Set-Content -LiteralPath (Join-Path $ThuMuc 'usbdk-bo-loc-truoc.json') -Encoding UTF8
    foreach ($x in $loc) {
        $moi = [string[]]@($x.GiaTri | Where-Object { $_ -ne 'UsbDk' })
        if ($moi.Count) { Set-ItemProperty -LiteralPath $x.Khoa -Name $x.Ten -Value $moi -Type MultiString -ErrorAction SilentlyContinue }
        else { Remove-ItemProperty -LiteralPath $x.Khoa -Name $x.Ten -ErrorAction SilentlyContinue }
    }
    if (@(Get-BoLocUsbDk).Count) { Write-Dong 'Không bỏ được UsbDk khỏi bộ lọc USB.'; $script:LyDoKet = 'không ghi được danh sách bộ lọc USB'; return $false }
    $tuChoi = Restart-BoDieuKhienUsb
    # bước bộ gỡ chính thức bỏ sót: yêu cầu Windows DỪNG driver
    & sc.exe stop UsbDk 2>$null | Out-Null
    for ($i = 0; $i -lt 40 -and (Get-DriverUsbDk) -notin 'STOPPED', 'KHONG_CO'; $i++) { Start-Sleep -Milliseconds 500 }
    if ((Get-DriverUsbDk) -in 'STOPPED', 'KHONG_CO') { Write-Dong 'Driver UsbDk đã dừng hẳn — gỡ được ngay, không cần khởi động lại.'; return $true }
    $script:LyDoKet = "driver vẫn $(Get-DriverUsbDk)"
    if ($tuChoi.Count) { $script:LyDoKet += "; bộ điều khiển không chịu nạp lại: $($tuChoi -join ', ')" }
    # TRẢ LẠI NGUYÊN TRẠNG: chưa xóa gì → máy dùng tiếp như trước, không rơi vào "dịch vụ chờ xóa"
    Write-Dong 'Chưa dừng được driver → trả lại bộ lọc như cũ, KHÔNG xóa gì.'
    foreach ($x in $loc) { Set-ItemProperty -LiteralPath $x.Khoa -Name $x.Ten -Value $x.GiaTri -Type MultiString -ErrorAction SilentlyContinue }
    $null = Restart-BoDieuKhienUsb
    return $false
}
# GỠ NÓNG bước 2 (chỉ gọi sau khi Dismount-UsbDk trả $true). $true = đã sạch, cài lại được ngay.
function Remove-UsbDkDaDung {
    Assert-DuocSua
    $cai = Get-DaCai '^UsbDk'
    if ($cai) { $null = Invoke-Msi @('/x', $cai.PSChildName) 'usbdk-go' }
    elseif (Test-Path -LiteralPath $UsbDkCtl) { try { $p = Start-Process -FilePath $UsbDkCtl -ArgumentList '-u' -PassThru -WindowStyle Hidden -ErrorAction Stop; if (-not $p.WaitForExit(90000)) { try { $p.Kill() } catch {} } } catch {} }
    if (Test-Path $UsbDkKhoa) { & sc.exe delete UsbDk 2>$null | Out-Null; Start-Sleep -Seconds 2 }
    if (Test-Path $UsbDkKhoa) {
        # driver đã dừng mà dịch vụ còn "chờ xóa" = có cửa sổ đang giữ tay cầm (services.msc, Device Manager…)
        Get-Process -Name mmc -ErrorAction SilentlyContinue | Stop-Process -Force -ErrorAction SilentlyContinue
        for ($i = 0; $i -lt 20 -and (Test-Path $UsbDkKhoa); $i++) { Start-Sleep -Milliseconds 500 }
    }
    if (Test-Path -LiteralPath $UsbDkSys) { Remove-Item -LiteralPath $UsbDkSys -Force -ErrorAction SilentlyContinue }
    if (Test-Path -LiteralPath $UsbDkThuMuc) { Remove-Item -LiteralPath $UsbDkThuMuc -Recurse -Force -ErrorAction SilentlyContinue }
    return (-not (Test-Path $UsbDkKhoa) -and -not (Test-Path -LiteralPath $UsbDkSys))
}
function Install-UsbDkMoi($msi) {
    Assert-DuocSua
    Write-Dong 'Cài mới UsbDk…'
    $ma = Invoke-Msi @('/i', "`"$msi`"") 'usbdk-cai'
    if (Test-MsiXong $ma) { return $ma }
    # cách dự phòng theo hướng dẫn của dự án UsbDk: bung gói rồi cài driver bằng UsbDkController -i để biết mã lỗi thật
    Write-Dong 'Bộ cài MSI lỗi — thử cài driver trực tiếp bằng UsbDkController -i…'
    $bung = Join-Path $ThuMuc 'usbdk-bung'
    $null = Start-Process msiexec.exe -ArgumentList @('/a', "`"$msi`"", '/qn', "TARGETDIR=`"$bung`"") -Wait -PassThru
    $c = Get-ChildItem -LiteralPath $bung -Recurse -Filter 'UsbDkController.exe' -ErrorAction SilentlyContinue | Select-Object -First 1
    if (-not $c) { return $ma }
    New-Item -ItemType Directory -Force $UsbDkThuMuc | Out-Null
    Copy-Item -Path (Join-Path $c.DirectoryName '*') -Destination $UsbDkThuMuc -Recurse -Force
    $p = Start-Process -FilePath $UsbDkCtl -ArgumentList '-i' -PassThru -WindowStyle Hidden
    $null = $p.Handle
    if (-not $p.WaitForExit(120000)) { try { $p.Kill() } catch {}; Write-Dong 'UsbDkController -i không trả lời (kẹt).'; return $ma }
    $y = @{ 0 = 'thành công'; 1 = 'thất bại'; 2 = 'thành công, đề nghị khởi động lại'; 4 = 'driver không khởi động được (kiểm tra chữ ký driver / Memory integrity)' }[$p.ExitCode]
    Write-Dong "UsbDkController -i trả mã $($p.ExitCode): $y"
    if ($p.ExitCode -eq 0) { return 0 }
    if ($p.ExitCode -eq 2) { return 3010 }
    return $ma
}
function Wait-RutThietBiApple {
    for ($i = 0; $i -lt 60; $i++) {
        $d = @(Get-PnpDevice -PresentOnly -ErrorAction SilentlyContinue | Where-Object { $_.InstanceId -match '^USB\\VID_05AC' })
        if ($d.Count -eq 0) { return }
        if ($i -eq 0) { Write-Host '    !! HÃY RÚT iPhone / iPad khỏi máy tính trước khi sửa UsbDk (đợi tối đa 60 giây)…' -ForegroundColor Yellow }
        Start-Sleep -Seconds 1
    }
    Write-Dong 'Vẫn còn thiết bị Apple đang cắm — làm tiếp.'
}
# Nghiệm thu chắc nhất: UsbDk có NHÌN THẤY iPhone không (VID 05AC trong danh sách thiết bị của driver). Bỏ qua được.
function Test-IPhoneQuaUsbDk {
    if ($KhongCho) { return }
    # GSM_SILENT: tool chạy script ẩn, không có cửa sổ để bấm phím
    $boQuaBangPhim = if ($env:GSM_SILENT) { '' } else { ', bấm phím để bỏ qua' }
    Write-Host "    >> Cắm iPhone / iPad (bất kỳ chế độ nào) để nghiệm thu UsbDk — đợi 45 giây$boQuaBangPhim…" -ForegroundColor Cyan
    if (-not $env:GSM_SILENT) { try { $Host.UI.RawUI.FlushInputBuffer() } catch {} }
    for ($i = 0; $i -lt 45; $i++) {
        if (-not $env:GSM_SILENT) { try { if ($Host.UI.RawUI.KeyAvailable) { $null = $Host.UI.RawUI.ReadKey('NoEcho,IncludeKeyDown'); break } } catch {} }
        if (@(Get-PnpDevice -PresentOnly -ErrorAction SilentlyContinue | Where-Object { $_.InstanceId -match '^USB\\VID_05AC' }).Count) {
            Start-Sleep -Seconds 2
            $null = Test-UsbDkChay $UsbDkCtl
            if ((Get-Content -LiteralPath (Join-Path $ThuMuc 'usbdk-liet-ke.txt') -Raw -ErrorAction SilentlyContinue) -match '05[Aa][Cc]') { Add-KetQua 'UsbDk + iPhone' 'OK' 'UsbDk đã nhìn thấy thiết bị Apple' }
            else { Add-KetQua 'UsbDk + iPhone' 'CẢNH BÁO' 'Windows thấy iPhone nhưng UsbDk chưa thấy — đổi sang cổng USB khác (ưu tiên cổng sau máy); vẫn không được thì khởi động lại khi tiện' }
            return
        }
        Start-Sleep -Seconds 1
    }
    Write-Dong 'Bỏ qua bước nghiệm thu bằng iPhone.'
}
function Request-RebootUsbDk($lyDo) {
    $khoiDong = "$((Get-CimInstance Win32_OperatingSystem).LastBootUpTime.ToString('s'))"
    $nho = $null; if (Test-Path -LiteralPath $TepUsbDk) { $nho = Get-Content -LiteralPath $TepUsbDk -Raw | ConvertFrom-Json }
    $daCho = 0; if ($nho) { $daCho = [int]$nho.SoLan }
    if ($nho -and $nho.KhoiDong -ne $khoiDong -and $daCho -ge 2) {
        Add-KetQua 'UsbDk' 'LỖI' "đã khởi động lại $daCho lần mà vẫn chưa được ($lyDo) — dừng vòng lặp, gửi thư mục báo cáo cho người hỗ trợ"
        return
    }
    $n = $daCho; if (-not $nho -or $nho.KhoiDong -ne $khoiDong) { $n = $daCho + 1 }
    @{ KhoiDong = $khoiDong; SoLan = $n } | ConvertTo-Json | Set-Content -LiteralPath $TepUsbDk -Encoding UTF8
    Add-KetQua 'UsbDk' 'CẦN REBOOT' "$lyDo — khởi động lại KHI TIỆN rồi bấm chạy lại (các mục khác đã xong; script tự làm tiếp UsbDk)"
}
function Set-UsbDkXong($chiTiet) { Add-KetQua 'UsbDk' 'OK' $chiTiet; Remove-Item -LiteralPath $TepUsbDk -Force -ErrorAction SilentlyContinue; Test-IPhoneQuaUsbDk }
# Thang sửa từ NHẸ tới NẶNG; đạt ở bậc nào thì dừng ở bậc đó.
function Repair-UsbDk($msi) {
    Assert-DuocSua
    $u = Get-TrangThaiUsbDk; Write-TrangThaiUsbDk $u
    if ([Environment]::OSVersion.Version.Build -ge 26100) { Write-Dong '⚠ Windows 11 24H2 trở lên: dự án UsbDk có người dùng báo treo máy / mất chuột phím USB sau khi cài (chưa được tác giả sửa) — bộ cứu USB được tạo trước khi đụng vào driver.' }

    # Bậc 1 — nhả kẹt: đóng chương trình đang giữ driver, bật lại driver. Không gỡ gì.
    Write-Dong '[Bậc 1] Nhả kẹt (không gỡ, không khởi động lại)…'
    Close-TienTrinhGiuUsbDk
    if ($u.DichVu -and $u.TepSys -and (Get-DriverUsbDk) -eq 'STOPPED') { & sc.exe start UsbDk 2>$null | Out-Null; Start-Sleep -Seconds 2 }
    $u = Get-TrangThaiUsbDk
    if ($u.Loai -eq 'TOT') { Set-UsbDkXong 'đang chạy tốt — không phải gỡ, không cần khởi động lại'; return }
    Write-TrangThaiUsbDk $u

    # Bậc 2 — trả lại tệp bị thiếu / hỏng
    if ($u.Loai -eq 'HONG' -and $u.MsiMa) {
        Write-Dong '[Bậc 2] Repair bằng bộ cài (chỉ trả lại tệp thư viện; theo mã nguồn, lệnh này KHÔNG cài lại driver — nghiệm thu mới quyết định)…'
        $null = Invoke-Msi @('/fa', $u.MsiMa) 'usbdk-sua'
        $u = Get-TrangThaiUsbDk
        if ($u.Loai -eq 'TOT') { Set-UsbDkXong 'sửa xong, chạy thử đạt — không cần khởi động lại'; return }
        Write-TrangThaiUsbDk $u
    }

    $khongAnToan = Test-AnToanNapLaiUsb
    if ($khongAnToan) { Add-KetQua 'UsbDk' 'LỖI' "chưa sửa tiếp vì $khongAnToan — chưa cần khởi động lại: tháo ổ USB rồi bấm chạy lại"; return }
    Wait-RutThietBiApple
    New-BoCuuUsb

    # Bậc 3 — nạp lại driver bằng cách khởi động lại bộ điều khiển USB (không khởi động lại máy)
    if ($u.Loai -eq 'HONG' -and $u.DichVu -and $u.TepSys -and $u.Ctl -and @($u.BoLoc).Count) {
        Write-Dong '[Bậc 3] Nạp lại bộ điều khiển USB…'
        $null = Restart-BoDieuKhienUsb
        if ((Get-DriverUsbDk) -eq 'STOPPED') { & sc.exe start UsbDk 2>$null | Out-Null }
        $u = Get-TrangThaiUsbDk
        if ($u.Loai -eq 'TOT') { Set-UsbDkXong 'nạp lại driver là chạy — không cần khởi động lại'; return }
        Write-TrangThaiUsbDk $u
    }

    # Bậc 4 — gỡ nóng rồi cài mới
    if ($u.Loai -ne 'CHUA_CAI') {
        Write-Dong '[Bậc 4] Gỡ nóng rồi cài mới…'
        $script:LyDoKet = ''
        if (-not (Dismount-UsbDk)) { Request-RebootUsbDk "Windows chưa nhả được driver cũ ($($script:LyDoKet)); đã trả lại nguyên trạng"; return }
        if (-not (Remove-UsbDkDaDung)) { Request-RebootUsbDk 'Windows còn giữ dịch vụ / tệp UsbDk cũ (đã tách khỏi bộ lọc USB nên khởi động an toàn)'; return }
        Write-Dong 'Đã gỡ sạch bản cũ.'
    }
    $ma = Install-UsbDkMoi $msi
    if (-not (Test-MsiXong $ma)) { Add-KetQua 'UsbDk' 'LỖI' "không cài được (mã $ma)"; Write-ChanDoanUsbDk; return }
    if ((Get-DriverUsbDk) -eq 'STOPPED') { & sc.exe start UsbDk 2>$null | Out-Null }
    # bộ cài báo "cần khởi động lại" chỉ vì có bộ điều khiển chưa nạp lại được (gồm cả bộ điều khiển ảo) → tự nạp lại bộ điều khiển THẬT rồi nghiệm thu
    Write-Dong 'Nghiệm thu: nạp lại bộ điều khiển USB thật rồi chạy thử driver…'
    $tuChoi = Restart-BoDieuKhienUsb
    $u = Get-TrangThaiUsbDk; Write-TrangThaiUsbDk $u
    if ($u.Loai -eq 'TOT' -and -not $tuChoi.Count) {
        $them = ''; if ($ma -eq 3010) { $them = ' (bộ cài đề nghị khởi động lại nhưng driver đã chạy và mọi cổng USB thật đã nạp lại → bỏ qua)' }
        Set-UsbDkXong "cài mới xong, chạy thử đạt — không cần khởi động lại$them"
    } elseif ($u.Loai -eq 'TOT') {
        Add-KetQua 'UsbDk' 'CẢNH BÁO' "driver đã chạy, nhưng chưa nạp lại được: $($tuChoi -join ', ') — cắm iPhone vào cổng khác; cổng đó chỉ dùng được sau khi khởi động lại (làm khi tiện)"
        Remove-Item -LiteralPath $TepUsbDk -Force -ErrorAction SilentlyContinue
        Test-IPhoneQuaUsbDk
    } else { Request-RebootUsbDk "đã cài nhưng driver chưa chạy (thử: $($u.Thu))" }
}
function Write-ChanDoanUsbDk {
    $hvci = (Get-ItemProperty 'HKLM:\SYSTEM\CurrentControlSet\Control\DeviceGuard\Scenarios\HypervisorEnforcedCodeIntegrity' -ErrorAction SilentlyContinue).Enabled
    Write-Dong "Memory integrity (Cách ly lõi): $(if ($hvci -eq 1) { 'ĐANG BẬT — có thể chặn driver cũ (script không tự tắt)' } else { 'đang tắt' })"
    $bd = Get-BoDieuKhienUsb
    Write-Dong "Bộ điều khiển USB thật: $(($bd.That | ForEach-Object { $_.FriendlyName }) -join ' | ')"
    if ($bd.Ao.Count) { Write-Dong "Bộ điều khiển USB ẢO: $(($bd.Ao | ForEach-Object { $_.FriendlyName }) -join ' | ') — bộ cài UsbDk cũng nạp lại chúng; đây là ứng viên làm nó đòi khởi động lại (chưa kiểm chứng)" }
    if ($bd.UsbQuaMang) { Write-Dong '⚠ Đang có thiết bị USB over Ethernet — cài UsbDk có thể làm đứt phiên USB qua mạng.' }
    $giu = @(Get-TienTrinhGiuUsbDk)
    if ($giu.Count) { Write-Dong "Chương trình đang giữ UsbDk: $(($giu | ForEach-Object { $_.ProcessName }) -join ', ')" }
    $l = Get-DaCai 'libusb'
    if ($l) { Write-Dong "Máy có cài $($l.DisplayName) — nếu UsbDk vẫn lỗi, thử gỡ bộ lọc libUSB (chưa có bằng chứng chắc chắn là xung đột)." }
}

# ───────────────────────── kiểm trước khi đụng vào máy ─────────────────────────
Write-Host '======================================================================'
Write-Host '  FIX APPLE BY THIEN PHAN GSM' -ForegroundColor White
if ($ChiKiemTra) { Write-Host '  CHẾ ĐỘ CHỈ KIỂM TRA — không sửa gì trên máy' -ForegroundColor Yellow }
Write-Host '======================================================================'
Write-Muc '[0] KIỂM TRA NGUYÊN LIỆU (trước khi đổi bất cứ thứ gì)'
$tepBonjour = Find-NguyenLieu $Bonjour 'Bonjour*.msi'
$tepITunes = Find-NguyenLieu $iTunes 'iTunes*.exe'
$tepUsbDk = Find-NguyenLieu $UsbDk 'UsbDk*.msi'
$hong = @()
if (-not [Environment]::Is64BitOperatingSystem) { $hong += 'Windows không phải 64-bit' }
foreach ($x in @(@('Bonjour64.msi', $tepBonjour, 'Apple Inc\.'), @('iTunes64.exe', $tepITunes, 'Apple Inc\.'), @('UsbDk64.msi', $tepUsbDk, 'Red Hat'))) {
    if (-not $x[1]) { $hong += "thiếu $($x[0])" }
    elseif (-not (Test-ChuKy $x[1] $x[2])) { $hong += "$($x[0]): chữ ký số không hợp lệ" }
    else { Write-Dong "$($x[0]) : $($x[1]) (chữ ký hợp lệ)" }
}
$tam = Join-Path $ThuMuc 'goi-itunes'
$msiAmds = $null; $msiITunes = $null; $verAmds = $null; $verITunes = $null
if (-not $hong.Count) {
    if (Expand-BoITunes $tepITunes $tam) {
        $msiAmds = Join-Path $tam 'AppleMobileDeviceSupport64.msi'
        $msiITunes = Join-Path $tam 'iTunes64.msi'
    }
    foreach ($m in $msiAmds, $msiITunes) { if (-not ($m -and (Test-Path -LiteralPath $m) -and (Test-ChuKy $m 'Apple Inc\.'))) { $hong += 'không tách được gói cài hợp lệ từ iTunes64.exe'; break } }
    if (-not $hong.Count) {
        $verAmds = Get-MsiThuocTinh $msiAmds 'ProductVersion'
        $verITunes = Get-MsiThuocTinh $msiITunes 'ProductVersion'
        Write-Dong "Trong iTunes64.exe: Apple Mobile Device Support $verAmds · iTunes $verITunes"
    }
}
if ($hong.Count) {
    Add-KetQua 'Nguyên liệu' 'LỖI' (($hong -join '; ') + ' — CHƯA đổi gì trên máy')
} else { Add-KetQua 'Nguyên liệu' 'OK' 'đủ và hợp lệ' }

# ───────────────────────── CHỈ KIỂM TRA ─────────────────────────
if ($ChiKiemTra) {
    Write-Muc '[1] TEMP + UAC'
    Write-Dong "ConsentPromptBehaviorAdmin = $((Get-ItemProperty $KhoaUac -ErrorAction SilentlyContinue).ConsentPromptBehaviorAdmin) · Everyone toàn quyền C:\Windows\Temp: $(Test-TempChoEveryone) (trống = không đọc được)"
    Write-Muc '[2] LOCKDOWN'
    if (Test-Path -LiteralPath $ThuMucLockdown) { Write-Dong "Có $(@(Get-ChildItem -LiteralPath $ThuMucLockdown -Force -ErrorAction SilentlyContinue).Count) mục" } else { Write-Dong 'Không có thư mục' }
    Write-Muc '[3] NGUỒN ĐIỆN (AC, DC — giây)'
    Write-Dong "Màn hình: $((Get-NguonDien 'SUB_VIDEO' 'VIDEOIDLE') -join ', ') · Ngủ: $((Get-NguonDien 'SUB_SLEEP' 'STANDBYIDLE') -join ', ') · Tiết kiệm điện USB: $((Get-NguonDien $UsbNhom $UsbMuc) -join ', ') (1 = đang bật)"
    Write-Muc '[4] GIỜ'
    $w = Get-Service w32time -ErrorAction SilentlyContinue; Write-Dong "Dịch vụ Windows Time: $($w.Status) · $(Get-Date -Format 'dd/MM/yyyy HH:mm:ss')"
    Write-Muc '[5] BONJOUR'
    $bj = Get-Service 'Bonjour Service' -ErrorAction SilentlyContinue; if ($bj) { Write-Dong "Dịch vụ: $($bj.Status)" } else { Write-Dong 'Chưa cài' }
    Write-Muc '[6] ITUNES'
    $st = Get-ITunesStore
    $phamVi = if ($st.MoiTaiKhoan) { '' } else { ' (mới xem được tài khoản đang dùng)' }
    if (-not $st.DocDuoc) { Write-Dong "iTunes bản Microsoft Store: không kiểm tra được ($($st.Loi))" }
    elseif ($st.Goi.Count -or $st.CaiSan.Count) { Write-Dong "iTunes bản Microsoft Store: CÓ ($(Format-ITunesStore $st))$phamVi → chạy thật sẽ gỡ rồi thay bằng bản EXE" }
    else { Write-Dong "iTunes bản Microsoft Store: không có$phamVi" }
    $am = Get-TrangThaiAmds; $it = Get-TrangThaiITunes
    Write-Dong "Apple Mobile Device Support: $(if ($am.DaCai) { $am.PhienBan } else { 'chưa cài' }) · dịch vụ: $($am.DichVu) · thiếu: $(if ($am.Thieu.Count) { $am.Thieu -join '; ' } else { 'không' })"
    Write-Dong "Driver usbaapl64 trong kho driver Windows: $(Test-DriverAppleTrongKho)"
    Write-Dong "iTunes: $(if ($it.DaCai) { $it.PhienBan } else { 'chưa cài' }) · thiếu: $(if ($it.Thieu.Count) { $it.Thieu -join '; ' } else { 'không' })"
    if ($verAmds) { Write-Dong "Nếu chạy thật: AMDS → $(Get-ViecCan $am $verAmds) · iTunes → $(Get-ViecCan $it $verITunes)   (GIU/CAI/NANGCAP/LAMLAI)" }
    Write-Muc '[7] USBDK'
    $u = Get-TrangThaiUsbDk; Write-TrangThaiUsbDk $u
    Write-Dong "Kết luận: $(@{ TOT = 'đang chạy tốt'; CHUA_CAI = 'chưa cài (sạch)'; HONG = 'HỎNG / còn sót dở dang → chạy thật sẽ đi thang sửa từ nhẹ tới nặng'; CHO_XOA = 'dịch vụ đang CHỜ XÓA → chạy thật sẽ thử nhả mà không khởi động lại' }[$u.Loai])"
    $o = @(Get-Disk -ErrorAction SilentlyContinue | Where-Object { $_.BusType -eq 'USB' }).Count
    Write-Dong "Ổ lưu trữ USB đang cắm: $o"
    Write-ChanDoanUsbDk
    Remove-Item -LiteralPath $tam -Recurse -Force -ErrorAction SilentlyContinue
    Write-Host ''; Write-Host "Báo cáo: $(Join-Path $ThuMuc 'bao-cao.txt')"
    try { Stop-Transcript | Out-Null } catch {}
    if ($hong.Count) { exit 1 }
    exit 0
}

# ───────────────────────── CHẠY THẬT ─────────────────────────
if (-not $hong.Count) {
    try { Save-GiaTriGoc } catch { Write-Dong "Không lưu được giá trị gốc: $($_.Exception.Message)" }

    # [1] TEMP + UAC
    Write-Muc '[1] TEMP + UAC'
    & icacls.exe 'C:\Windows\Temp' '/grant:r' '*S-1-1-0:(OI)(CI)F' '/T' '/C' '/Q' 2>$null | Out-Null
    if (Test-TempChoEveryone) { Add-KetQua 'Quyền thư mục Temp' 'OK' 'Everyone có toàn quyền C:\Windows\Temp' } else { Add-KetQua 'Quyền thư mục Temp' 'LỖI' 'chưa cấp được quyền cho C:\Windows\Temp' }
    Set-ItemProperty $KhoaUac -Name ConsentPromptBehaviorAdmin -Type DWord -Value 0 -ErrorAction SilentlyContinue
    if ((Get-ItemProperty $KhoaUac).ConsentPromptBehaviorAdmin -eq 0) { Add-KetQua 'UAC' 'OK' "đã tắt hộp hỏi quyền quản trị cho cả máy (khôi phục: $(Join-Path $Goc 'khoi-phuc.ps1'))" } else { Add-KetQua 'UAC' 'LỖI' 'không ghi được registry (có thể bị chính sách máy chặn)' }

    # [2] LOCKDOWN (sao lưu trước, xóa sau)
    Write-Muc '[2] DỌN DẸP THƯ MỤC APPLE LOCKDOWN'
    if (-not (Test-Path -LiteralPath $ThuMucLockdown)) { Add-KetQua 'Lockdown' 'BỎ QUA' 'không có thư mục' }
    else {
        $muc = @(Get-ChildItem -LiteralPath $ThuMucLockdown -Force -ErrorAction SilentlyContinue)
        if (-not $muc.Count) { Add-KetQua 'Lockdown' 'OK' 'đang trống sẵn' }
        else {
            Stop-Service 'Apple Mobile Device Service' -Force -ErrorAction SilentlyContinue
            $zip = Join-Path $ThuMuc 'lockdown-sao-luu.zip'
            # nén bằng .NET để lấy CẢ tệp ẩn (Compress-Archive bỏ sót tệp ẩn, trong khi bước xóa xóa cả tệp ẩn)
            try { Add-Type -AssemblyName System.IO.Compression.FileSystem; [IO.Compression.ZipFile]::CreateFromDirectory($ThuMucLockdown, $zip) } catch { Write-Dong "Sao lưu lỗi: $($_.Exception.Message)"; Remove-Item -LiteralPath $zip -Force -ErrorAction SilentlyContinue }
            if (-not (Test-Path -LiteralPath $zip)) { Add-KetQua 'Lockdown' 'LỖI' 'không sao lưu được nên KHÔNG xóa' }
            else {
                $muc | Remove-Item -Recurse -Force -ErrorAction SilentlyContinue
                $con = @(Get-ChildItem -LiteralPath $ThuMucLockdown -Force -ErrorAction SilentlyContinue).Count
                if ($con -eq 0) { Add-KetQua 'Lockdown' 'OK' "đã xóa sạch $($muc.Count) mục (sao lưu: $zip)" } else { Add-KetQua 'Lockdown' 'LỖI' "còn $con mục chưa xóa được" }
            }
            Start-Service 'Apple Mobile Device Service' -ErrorAction SilentlyContinue
        }
    }

    # [3] NGUỒN ĐIỆN
    Write-Muc '[3] THIẾT LẬP NGUỒN ĐIỆN'
    $loiPw = 0
    foreach ($x in @(@('SUB_VIDEO', 'VIDEOIDLE', 1800), @('SUB_SLEEP', 'STANDBYIDLE', 3600), @($UsbNhom, $UsbMuc, 0))) {
        foreach ($c in '/SETACVALUEINDEX', '/SETDCVALUEINDEX') { & powercfg.exe $c SCHEME_CURRENT $x[0] $x[1] $x[2] 2>$null | Out-Null; if ($LASTEXITCODE -ne 0) { $loiPw++ } }
    }
    & powercfg.exe /SETACTIVE SCHEME_CURRENT 2>$null | Out-Null; if ($LASTEXITCODE -ne 0) { $loiPw++ }
    if ($loiPw -eq 0) { Add-KetQua 'Nguồn điện' 'OK' 'màn hình 30 phút · ngủ 60 phút · tắt tiết kiệm điện cổng USB' } else { Add-KetQua 'Nguồn điện' 'CẢNH BÁO' "$loiPw lệnh powercfg không thành công" }

    # [4] GIỜ
    Write-Muc '[4] HỆ THỐNG ĐỒNG BỘ THỜI GIAN THÔNG MINH'
    Write-Dong 'Dừng, đăng ký lại và khởi động dịch vụ Windows Time…'
    & net.exe stop w32time 2>$null | Out-Null
    & w32tm.exe /unregister 2>$null | Out-Null
    Start-Sleep -Seconds 2
    & w32tm.exe /register 2>$null | Out-Null
    & net.exe start w32time 2>$null | Out-Null
    $xong = $null
    foreach ($mc in 'time.windows.com', 'time.nist.gov') {
        Write-Dong "Đồng bộ với $mc…"
        & w32tm.exe /config "/manualpeerlist:$mc" /syncfromflags:manual /reliable:YES /update 2>$null | Out-Null
        for ($lan = 1; $lan -le 2 -and -not $xong; $lan++) {
            Start-Sleep -Seconds 3
            $ra = & w32tm.exe /resync /rediscover 2>&1
            if ($LASTEXITCODE -eq 0) { $xong = $mc } else { Write-Dong "  lần $lan chưa được: $(($ra | Select-Object -Last 1))" }
        }
        if ($xong) { break }
    }
    if ($xong) { Add-KetQua 'Đồng bộ giờ' 'OK' "đồng bộ được với $xong" } else { Add-KetQua 'Đồng bộ giờ' 'LỖI' 'cả hai máy chủ không đồng bộ được — kiểm tra Internet' }

    # [5] BONJOUR
    Write-Muc '[5] BONJOUR SERVICE'
    $coSan = [bool](Get-Service 'Bonjour Service' -ErrorAction SilentlyContinue)
    if (-not $coSan) { $null = Invoke-Msi @('/i', "`"$tepBonjour`"") 'bonjour' }
    if (Start-DichVu 'Bonjour Service') { Add-KetQua 'Bonjour' 'OK' $(if ($coSan) { 'đã có sẵn, dịch vụ đang chạy' } else { 'đã cài mới, dịch vụ đang chạy' }) }
    elseif ($coSan) {
        $null = Invoke-Msi @('/i', "`"$tepBonjour`"", 'REINSTALL=ALL', 'REINSTALLMODE=vamus') 'bonjour-sua'
        if (Start-DichVu 'Bonjour Service') { Add-KetQua 'Bonjour' 'OK' 'đã sửa, dịch vụ đang chạy' } else { Add-KetQua 'Bonjour' 'LỖI' 'dịch vụ không chạy được sau khi sửa' }
    } else { Add-KetQua 'Bonjour' 'LỖI' 'cài xong mà không có / không chạy được dịch vụ' }

    # [6] ITUNES — cài thẳng từng gói, nghiệm thu bằng trạng thái thật
    Write-Muc '[6] ITUNES'
    # đóng tiến trình TRƯỚC rồi mới gỡ / cài
    Get-Process -Name iTunes, iTunesHelper, AppleMobileDeviceHelper, AppleMobileDeviceProcess, SetupAdmin -ErrorAction SilentlyContinue | Stop-Process -Force -ErrorAction SilentlyContinue
    # chỉ tới được đây khi bộ iTunes EXE đã qua kiểm tra ở bước [0] → không bao giờ gỡ bản Store khi chưa có bản thay thế trong tay
    Remove-ITunesStore
    if (Get-AppxPackage 'AppleInc.AppleDevices' -AllUsers -ErrorAction SilentlyContinue) { Add-KetQua 'App Apple Devices' 'CẢNH BÁO' 'máy đang cài app "Apple Devices" (Store) — có thể tranh driver với iTunes; nếu iPhone không nhận, gỡ app này' }

    # 6a. Apple Mobile Device Support TRƯỚC (phần để máy tính và phần mềm khác nhận iPhone)
    $am = Get-TrangThaiAmds
    $viec = Get-ViecCan $am $verAmds
    Write-Dong "Apple Mobile Device Support: đang có $(if ($am.DaCai) { $am.PhienBan } else { 'chưa cài' }) · gói $verAmds · việc cần làm: $viec"
    if ($viec -ne 'GIU') { $am = Install-Goi 'amds' $msiAmds { Get-TrangThaiAmds } $viec }
    # 6b. iTunes
    $it = Get-TrangThaiITunes
    $viec = Get-ViecCan $it $verITunes
    Write-Dong "iTunes: đang có $(if ($it.DaCai) { $it.PhienBan } else { 'chưa cài' }) · gói $verITunes · việc cần làm: $viec"
    if ($viec -ne 'GIU') { $it = Install-Goi 'itunes' $msiITunes { Get-TrangThaiITunes } $viec }
    # 6c. kiểm lại AMDS sau khi đụng tới iTunes
    $am = Get-TrangThaiAmds
    if (-not $am.Khoe) { Write-Dong "AMDS thiếu sau bước iTunes ($($am.Thieu -join '; ')) — cài lại."; $am = Install-Goi 'amds-lai' $msiAmds { Get-TrangThaiAmds } (Get-ViecCan $am $verAmds) }
    # bộ cài đề nghị khởi động lại VÀ nghiệm thu chưa đạt thì mới bắt buộc
    if ((-not $am.Khoe -or -not $it.Khoe) -and @($script:GoiYReboot | Where-Object { $_ -match '^(amds|itunes)' }).Count) { Add-KetQua 'iTunes / driver Apple' 'CẦN REBOOT' 'bộ cài cần khởi động lại mới hoàn tất — làm khi tiện rồi chạy lại' }
    # 6d. dịch vụ + driver
    $chay = Start-DichVu 'Apple Mobile Device Service'
    if (-not (Test-DriverAppleTrongKho) -and $am.Inf -and (Test-Path -LiteralPath $am.Inf)) { Write-Dong 'Nạp driver usbaapl64 vào Windows…'; & pnputil.exe /add-driver $am.Inf /install | Out-Null }
    $coDriver = Test-DriverAppleTrongKho
    if ($am.Khoe -and (Compare-PhienBan $am.PhienBan $verAmds) -lt 0) { Add-KetQua 'Apple Mobile Device Support' 'CẢNH BÁO' "vẫn là bản cũ $($am.PhienBan) (gói có $verAmds) — nâng cấp chưa thành, xem nhật ký msi" }
    elseif ($am.Khoe) { Add-KetQua 'Apple Mobile Device Support' 'OK' "bản $($am.PhienBan), đủ tệp + registry" } else { Add-KetQua 'Apple Mobile Device Support' 'LỖI' ($am.Thieu -join '; ') }
    if ($chay) { Add-KetQua 'Dịch vụ Apple' 'OK' 'Apple Mobile Device Service đang chạy' } else { Add-KetQua 'Dịch vụ Apple' 'LỖI' 'Apple Mobile Device Service không chạy' }
    if ($coDriver) { Add-KetQua 'Driver iPhone' 'OK' 'usbaapl64 đã có trong Windows' } else { Add-KetQua 'Driver iPhone' 'LỖI' 'chưa nạp được usbaapl64' }
    if ($it.Khoe -and (Compare-PhienBan $it.PhienBan $verITunes) -lt 0) { Add-KetQua 'iTunes' 'CẢNH BÁO' "vẫn là bản cũ $($it.PhienBan) (gói có $verITunes) — nâng cấp chưa thành, xem nhật ký msi" }
    elseif ($it.Khoe) { Add-KetQua 'iTunes' 'OK' "bản $($it.PhienBan)" } else { Add-KetQua 'iTunes' 'LỖI' ($it.Thieu -join '; ') }

    # [7] USBDK — thang sửa từ nhẹ tới nặng, hạn chế tối đa việc khởi động lại máy
    Write-Muc '[7] USBDK DRIVER'
    Repair-UsbDk $tepUsbDk
    Remove-Item -LiteralPath $tam -Recurse -Force -ErrorAction SilentlyContinue
}
# ───────────────────────── KẾT LUẬN TỔNG ─────────────────────────
Write-Host ''
Write-Host '======================================================================'
Write-Host '  KẾT LUẬN TỔNG'
$script:KetQua | ForEach-Object { Write-Host ("    {0,-12} {1}: {2}" -f "[$($_.Loai)]", $_.Muc, $_.ChiTiet) }
$soLoi = @($script:KetQua | Where-Object { $_.Loai -eq 'LỖI' }).Count
$ma = 0
if ($soLoi) { $ma = 1; Write-Host "    - Trạng thái : THẤT BẠI (X) — $soLoi mục lỗi, xem các dòng [LỖI] ở trên" -ForegroundColor Red }
if ($script:CanReboot) { if (-not $soLoi) { $ma = 2; Write-Host '    - Trạng thái : CHƯA HOÀN TẤT (!)' -ForegroundColor Yellow }; Write-Host '    => Hành động : KHỞI ĐỘNG LẠI máy tính rồi chạy lại để nghiệm thu' -ForegroundColor Yellow }
if ($ma -eq 0) { Write-Host '    - Trạng thái : HOÀN TẤT (V) — mở tool và làm việc!' -ForegroundColor Green }
if ($ma -eq 0 -and $script:GoiYReboot.Count) { Write-Host "    (Gợi ý, KHÔNG bắt buộc: bộ cài $(($script:GoiYReboot | Select-Object -Unique) -join ', ') đề nghị khởi động lại — làm khi tiện.)" -ForegroundColor DarkGray }
Write-Host "    - Báo cáo    : $(Join-Path $ThuMuc 'bao-cao.txt')"
Write-Host '======================================================================'
try { Stop-Transcript | Out-Null } catch {}
# chạy ẩn trong tool thì kết luận đã nằm ở nhật ký: không đếm ngược, không chờ phím (chờ là treo, vì không có cửa sổ)
if (-not $KhongCho -and -not $env:GSM_SILENT) {
    try {
        $Host.UI.RawUI.FlushInputBuffer()
        if ($ma -eq 0) {
            for ($i = 30; $i -gt 0 -and -not $Host.UI.RawUI.KeyAvailable; $i--) { Write-Host -NoNewline "`rTự đóng sau $i giây (bấm phím để đóng ngay)…  "; Start-Sleep -Seconds 1 }
        } else {
            Write-Host 'Bấm phím bất kỳ để đóng…'
            $null = $Host.UI.RawUI.ReadKey('NoEcho,IncludeKeyDown')
        }
    } catch {}
}
exit $ma

# Mở 3uTools trên máy này (bản V3 hoặc V9 — có bản nào mở bản đó); không có bản nào thì mới tải bộ cài (nguyên liệu) về, cài, rồi mở.
# @algo mo-3utools | Mở 3uTools (chưa có thì tự cài) | thuong
# @input 3utools | tool | Bộ cài 3uTools | 3utools-setup
# @lazy 3utools
#
# Mã thoát: 0 = xong · 1 = lỗi · 42 = máy chưa có 3uTools, xin tool tải bộ cài rồi chạy lại.
# Chỉ kiểm tra (không mở, không cài): đặt tên nút có chữ "chỉ kiểm tra", hoặc chạy với -ChiKiemTra.
param([switch]$ChiKiemTra)

$ErrorActionPreference = 'Stop'
try { [Console]::OutputEncoding = [Text.Encoding]::UTF8 } catch {}

# Tên tệp chạy của cả 2 dòng V3 / V9: 3uTools.exe, 3uTools9.exe, 3uToolsV3.exe… (KHÔNG khớp 3uViewer, trình gỡ, bộ cài 3uTools_..._Setup)
$MauExe = '(?i)^3uTools\s*(V?\d+)?\.exe$'
$MauTienTrinh = '(?i)^3uTools\s*(V?\d+)?$'
$ChoCaiToiDaPhut = 30   # thời gian tối đa chờ người dùng bấm xong bộ cài
$ChoSauCaiGiay = 20     # bộ cài đã thoát mà chưa thấy 3uTools: chờ thêm
$NhipMs = 1000

function Write-Dong([string]$s, [string]$mau = 'Gray') { Write-Host $s -ForegroundColor $mau }

# --- 1. Tìm 3uTools đã cài ----------------------------------------------------
function Get-KhoaGoCai {
    Get-ItemProperty -Path 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\*',
        'HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall\*',
        'HKCU:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\*' -ErrorAction SilentlyContinue |
        Where-Object { $_.DisplayName -match '(?i)^3u\s?Tools' }
}

function Get-DuongDanDangKy {
    foreach ($k in 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\App Paths\*',
        'HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\App Paths\*') {
        Get-ItemProperty -Path $k -ErrorAction SilentlyContinue | Where-Object { $_.PSChildName -match $MauExe } |
            ForEach-Object { $_.'(default)' }
    }
}

function Get-GocTimKiem {
    $goc = @($env:ProgramFiles, ${env:ProgramFiles(x86)}, $env:ProgramW6432)
    foreach ($o in [IO.DriveInfo]::GetDrives()) {
        if ($o.DriveType -eq 'Fixed' -and $o.IsReady) {
            $goc += $o.Name
            $goc += (Join-Path $o.Name 'Program Files')
            $goc += (Join-Path $o.Name 'Program Files (x86)')
        }
    }
    $goc | Where-Object { $_ } | Select-Object -Unique
}

# Mọi thư mục tên 3uTools* (3uToolsV3, 3uTools9, 3uToolsV9, 3uTools…) ngay dưới các gốc trên
function Get-ThuMucThuongGap {
    foreach ($g in @(Get-GocTimKiem)) {
        Get-ChildItem -LiteralPath $g -Directory -Filter '3u*' -ErrorAction SilentlyContinue |
            Where-Object { $_.Name -match '(?i)^3u\s?Tools' } | ForEach-Object { $_.FullName }
    }
}
# Lối tắt (bắt được cả trường hợp cài vào thư mục tự chọn mà registry thiếu)
function Get-DichLoiTat {
    $noi = @("$env:PUBLIC\Desktop", "$env:USERPROFILE\Desktop",
        "$env:ProgramData\Microsoft\Windows\Start Menu\Programs", "$env:APPDATA\Microsoft\Windows\Start Menu\Programs")
    try {
        $vo = New-Object -ComObject WScript.Shell
        foreach ($n in $noi) {
            Get-ChildItem -LiteralPath $n -Recurse -Filter '*3u*.lnk' -ErrorAction SilentlyContinue |
                ForEach-Object { $vo.CreateShortcut($_.FullName).TargetPath }
        }
    } catch {}
}

# Chuỗi lấy từ registry có thể kèm dấu nháy / ",0" → đường dẫn sạch
function ConvertTo-DuongDan([string]$s) {
    if (-not $s) { return '' }
    $s = $s.Trim()
    if ($s.StartsWith('"')) { return $s.Substring(1).Split('"')[0] }
    return ($s -replace ',\s*-?\d+$', '')
}

function Test-LaBanCai([string]$p) {
    if (-not $p) { return $false }
    try {
        return ([IO.Path]::GetFileName($p) -match $MauExe) -and (Test-Path -LiteralPath $p -PathType Leaf)
    } catch { return $false }
}

# Tìm tệp chạy 3uTools bên trong 1 thư mục cài, hoặc $null
function Find-TrongThuMuc([string]$thuMuc) {
    if (-not $thuMuc) { return $null }
    try {
        $t = Get-ChildItem -LiteralPath $thuMuc -File -Filter '3uTools*.exe' -ErrorAction SilentlyContinue |
            Where-Object { $_.Name -match $MauExe } | Sort-Object Name | Select-Object -First 1
        if ($t) { return $t.FullName }
    } catch {}
    return $null
}

# Trả đường dẫn tệp chạy 3uTools đã cài (V3 hoặc V9 — bản nào tìm thấy trước), hoặc $null
function Find-3uTools {
    foreach ($k in @(Get-KhoaGoCai)) {
        $ung = @()
        $ung += ConvertTo-DuongDan $k.DisplayIcon
        $ung += Find-TrongThuMuc (ConvertTo-DuongDan $k.InstallLocation)
        $go = ConvertTo-DuongDan $k.UninstallString
        if ($go -like '*.exe') { try { $ung += Find-TrongThuMuc (Split-Path -Parent $go) } catch {} }
        foreach ($u in $ung) { if (Test-LaBanCai $u) { return $u } }
    }
    foreach ($p in @(Get-DuongDanDangKy)) { $u = ConvertTo-DuongDan $p; if (Test-LaBanCai $u) { return $u } }
    foreach ($d in @(Get-ThuMucThuongGap)) {
        $u = Find-TrongThuMuc $d
        if (Test-LaBanCai $u) { return $u }
    }
    foreach ($p in @(Get-DichLoiTat)) { if (Test-LaBanCai $p) { return $p } }
    return $null
}

# --- 2. Mở --------------------------------------------------------------------
# $boQua = mã tiến trình bộ cài đang chạy (phòng bộ cài đặt tên giống app, vd 3uTools9.exe)
function Get-TienTrinhDangMo([int]$boQua = 0) {
    Get-Process -ErrorAction SilentlyContinue | Where-Object { $_.ProcessName -match $MauTienTrinh -and $_.Id -ne $boQua } | Select-Object -First 1
}

# Đưa cửa sổ đang mở lên trước (Windows có thể không cho vì 3uTools chạy quyền Admin — khi đó chỉ báo)
function Show-CuaSo($tienTrinh) {
    try {
        Add-Type -AssemblyName Microsoft.VisualBasic
        [Microsoft.VisualBasic.Interaction]::AppActivate([int]$tienTrinh.Id)
        return $true
    } catch { return $false }
}

function Start-TienTrinh([string]$tep, [string]$thamSo) {
    $tuyChon = @{ FilePath = $tep; PassThru = $true; WorkingDirectory = (Split-Path -Parent $tep) }
    if ($thamSo) { $tuyChon.ArgumentList = $thamSo }
    Start-Process @tuyChon
}

function Open-3uTools([string]$exe) {
    try {
        Start-TienTrinh $exe '' | Out-Null
    } catch {
        Write-Dong "✖ Không mở được 3uTools: $($_.Exception.Message)" Red
        Write-Dong '  (3uTools cần quyền quản trị — bấm "Yes" ở hộp hỏi của Windows.)' Yellow
        return 1
    }
    Write-Dong "✔ Đã mở 3uTools: $exe" Green
    return 0
}

# --- 3. Cài -------------------------------------------------------------------
# Chọn tệp bộ cài trong gói nguyên liệu: .exe / .msi, ưu tiên tên có setup / install / 3uTools, rồi tệp lớn nhất
function Find-BoCai([string]$nguon) {
    if (Test-Path -LiteralPath $nguon -PathType Leaf) { return (Get-Item -LiteralPath $nguon) }
    $ds = @(Get-ChildItem -LiteralPath $nguon -Recurse -File -ErrorAction SilentlyContinue |
        Where-Object { ($_.Extension -ieq '.exe' -or $_.Extension -ieq '.msi') -and $_.Name -notmatch '(?i)^unins' })
    $ds | Sort-Object @{ e = { if ($_.Name -match '(?i)setup|install') { 2 } elseif ($_.Name -match '(?i)3u') { 1 } else { 0 } }; Descending = $true },
        @{ e = { $_.Length }; Descending = $true } | Select-Object -First 1
}

function Get-ChuKy([string]$tep) { (Get-AuthenticodeSignature -LiteralPath $tep).Status.ToString() }

function Get-BangTienTrinh { Get-CimInstance Win32_Process -ErrorAction SilentlyContinue | Select-Object ProcessId, ParentProcessId, Name }

# Còn tiến trình con / cháu nào của bộ cài đang chạy không (bộ cài kiểu "vỏ" thoát sớm, con mới là đứa cài).
# $daThay nhớ các mã đã gặp để cha thoát rồi vẫn lần ra cháu. Không lần xuống dưới 3uTools (bộ cài tự mở app).
function Test-ConDangChay([int]$goc, [hashtable]$daThay) {
    $daThay[$goc] = $true
    $bang = @(Get-BangTienTrinh)
    do {
        $them = $false
        foreach ($t in $bang) {
            if ($t.Name -notmatch $MauExe -and $daThay.ContainsKey([int]$t.ParentProcessId) -and -not $daThay.ContainsKey([int]$t.ProcessId)) {
                $daThay[[int]$t.ProcessId] = $true; $them = $true
            }
        }
    } while ($them)
    foreach ($t in $bang) {
        if ([int]$t.ProcessId -ne $goc -and $daThay.ContainsKey([int]$t.ProcessId) -and $t.Name -notmatch $MauExe) { return $true }
    }
    return $false
}

# Chạy bộ cài và ĐỢI cài xong. Trả đường dẫn 3uTools.exe, hoặc $null
function Install-3uTools([IO.FileInfo]$boCai) {
    try {
        if ($boCai.Extension -ieq '.msi') {
            $p = Start-TienTrinh "$env:SystemRoot\System32\msiexec.exe" "/i `"$($boCai.FullName)`""
        } else {
            $p = Start-TienTrinh $boCai.FullName ''
        }
    } catch {
        Write-Dong "✖ Không chạy được bộ cài: $($_.Exception.Message)" Red
        return $null
    }
    Write-Dong '▶ Bộ cài đã mở — làm theo các bước trên cửa sổ cài đặt. Cài xong tool sẽ tự mở 3uTools.' Cyan
    $daThay = @{}
    $han = (Get-Date).AddMinutes($ChoCaiToiDaPhut)
    $hanSau = $null
    while ((Get-Date) -lt $han) {
        $conChay = Test-ConDangChay ([int]$p.Id) $daThay
        if ($p.HasExited -and -not $conChay) {
            $exe = Find-3uTools
            if ($exe) { return $exe }
            if (-not $hanSau) { $hanSau = (Get-Date).AddSeconds($ChoSauCaiGiay) }
            if ((Get-Date) -ge $hanSau) { return $null }
        } else {
            $hanSau = $null
            # bộ cài tự mở 3uTools ở bước cuối = đã cài xong
            if (Get-TienTrinhDangMo ([int]$p.Id)) { $exe = Find-3uTools; if ($exe) { return $exe } }
        }
        Start-Sleep -Milliseconds $NhipMs
    }
    Write-Dong "✖ Chờ quá $ChoCaiToiDaPhut phút mà bộ cài chưa xong." Red
    return $null
}

# --- Luồng chính --------------------------------------------------------------
function Invoke-Chinh([bool]$chiKiemTra, [string]$nguonBoCai) {
    $exe = Find-3uTools
    if ($chiKiemTra) {
        if ($exe) { Write-Dong "✔ Máy đã có 3uTools: $exe" Green } else { Write-Dong 'ℹ Máy chưa cài 3uTools.' Yellow }
        if (Get-TienTrinhDangMo) { Write-Dong 'ℹ 3uTools đang chạy.' } else { Write-Dong 'ℹ 3uTools chưa chạy.' }
        Write-Dong 'Chế độ chỉ kiểm tra — không mở, không cài.' Cyan
        return 0
    }

    $dangMo = Get-TienTrinhDangMo
    if ($dangMo) {
        if (Show-CuaSo $dangMo) { Write-Dong '✔ 3uTools đang mở sẵn — đã gọi lên trước (chưa thấy thì bấm biểu tượng ở Taskbar).' Green }
        else { Write-Dong '✔ 3uTools đang mở sẵn (xem ở thanh Taskbar / khay hệ thống).' Green }
        return 0
    }
    if ($exe) { return (Open-3uTools $exe) }

    # chưa cài: chưa có bộ cài trong tay thì xin tool tải về rồi chạy lại
    if (-not $nguonBoCai) {
        Write-Dong 'ℹ Máy chưa cài 3uTools — cần tải bộ cài.' Yellow
        return 42
    }
    $boCai = Find-BoCai $nguonBoCai
    if (-not $boCai) {
        Write-Dong "✖ Nguyên liệu không có tệp cài đặt (.exe / .msi): $nguonBoCai" Red
        return 1
    }
    $chuKy = Get-ChuKy $boCai.FullName
    if ($chuKy -eq 'HashMismatch') {
        Write-Dong "✖ Bộ cài $($boCai.Name) đã bị sửa đổi (chữ ký số không khớp) — không chạy. Hãy đưa bộ cài khác lên kho." Red
        return 1
    }
    if ($chuKy -ne 'Valid') { Write-Dong "⚠ Bộ cài $($boCai.Name) không có chữ ký số hợp lệ ($chuKy) — vẫn chạy vì đây là tệp bạn đưa lên kho." Yellow }
    Write-Dong "▶ Cài 3uTools từ $($boCai.Name)…" Cyan
    $exe = Install-3uTools $boCai
    if (-not $exe) {
        Write-Dong '✖ Chưa thấy 3uTools sau khi chạy bộ cài (đã hủy giữa chừng, hoặc cài lỗi).' Red
        return 1
    }
    Write-Dong "✔ Đã cài xong 3uTools: $exe" Green
    if (Get-TienTrinhDangMo) { Write-Dong '✔ 3uTools đã được bộ cài mở sẵn.' Green; return 0 }
    return (Open-3uTools $exe)
}

$chi = $ChiKiemTra.IsPresent -or ("$env:GSM_BUTTON" -match '(?i)chỉ kiểm tra')
try {
    $ma = Invoke-Chinh $chi "$env:GSM_IN_3UTOOLS"
} catch {
    Write-Dong "✖ Lỗi: $($_.Exception.Message)" Red
    $ma = 1
}
if ($ma -eq 1 -and -not $env:GSM_SILENT) { Start-Sleep -Seconds 8 }   # chạy có cửa sổ: chừa thời gian đọc lỗi trước khi cửa sổ đóng
exit $ma
